visual.source:
flowchart TB
  subgraph G1["棚卸しと構成"]
    INV@{ svc: "AWS Systems Manager", label: "Inventory<br/>ノードの情報を集める" }
    CFG@{ svc: "AWS Config", label: "AWS Config<br/>リソースの構成と履歴" }
  end
  subgraph G2["パッチ"]
    PM@{ svc: "AWS Systems Manager", label: "Patch Manager<br/>パッチの方法と準拠" }
  end
  subgraph G3["あるべき状態"]
    SM@{ svc: "AWS Systems Manager", label: "State Manager<br/>ほかの実行方法と比べる" }
  end
  subgraph G4["準拠を保つ"]
    CO@{ svc: "AWS Systems Manager", label: "Compliance<br/>準拠の状態を見る" }
    REM@{ svc: "AWS Config", label: "AWS Config<br/>ルールに合わない<br/>物を直す" }
  end
  subgraph G5["複雑な処理"]
    SF@{ svc: "AWS Step Functions", label: "Lambda と<br/>Step Functions" }
  end
  G1 ~~~ G2
  G2 ~~~ G3
  G3 ~~~ G4
  G4 ~~~ G5

flowchart TB
  PM@{ svc: "AWS Systems Manager", label: "Patch Manager<br/>パッチの準拠" }
  SM@{ svc: "AWS Systems Manager", label: "State Manager<br/>association の準拠" }
  CO@{ svc: "AWS Systems Manager", label: "Compliance<br/>今の準拠のデータ" }
  F["多くの管理対象のノード"]
  PM -- "既定で表示" --> CO
  SM -- "既定で表示" --> CO
  CO -- "スキャン" --> F

flowchart TB
  subgraph G1["棚卸しと構成"]
    INV@{ svc: "AWS Systems Manager", label: "Inventory<br/>S3 に集めて調べる" }
    CFG@{ svc: "AWS Config", label: "AWS Config<br/>構成の関係と履歴" }
  end
  subgraph G2["パッチ"]
    PM@{ svc: "AWS Systems Manager", label: "Patch Manager<br/>物差しは patch baseline" }
  end
  subgraph G3["あるべき状態"]
    SM@{ svc: "AWS Systems Manager", label: "State Manager<br/>association で保つ" }
  end
  subgraph G4["準拠を保つ"]
    CO@{ svc: "AWS Systems Manager", label: "Compliance<br/>既定で 2 つのデータ" }
    REM@{ svc: "AWS Config", label: "AWS Config<br/>Automation の<br/>文書で修復" }
  end
  subgraph G5["複雑な処理"]
    SF@{ svc: "AWS Step Functions", label: "Lambda の再試行と<br/>Standard・Express" }
  end
  G1 ~~~ G2
  G2 ~~~ G3
  G3 ~~~ G4
  G4 ~~~ G5
